arguments.new_string:
// Inherit the creator's runtime config (API key env + model)
// so the new agent is runnable immediately. Agents hired with
// a bare config fail every run with groq_missing_api_key.
const creatorCfg = ctx.config && typeof ctx.config === "object" ? ctx.config : {};
const adapterConfig = {};
if (creatorCfg.env && typeof creatorCfg.env === "object") {
    adapterConfig.env = creatorCfg.env;
}
if (typeof creatorCfg.model === "string" && creatorCfg.model) {
    adapterConfig.model = creatorCfg.model;
}
const r = await call("POST", `/api/companies/${agent.companyId}/agents`, {
    name: args.name,
    role: args.role,
    title: args.title ?? "",
    systemPrompt: args.systemPrompt,
    adapterType: args.adapterType ?? "groq_local",
    ...(Object.keys(adapterConfig).length > 0 ? { adapterConfig } : {}),
});
if (!r.ok)
    return r;
return { ok: true, agent: r.result };
